"""Guion tecnico de «Quien paga la gasolinera que esta a 20 metros de otra gasolinera» — planos libres.

    python gasolineras.py            -> vox/gasolineras.spec.json

Los numeros de fragmento son los de la locucion (79). Fuentes: config/guion_gasolineras.md.
"""
from planos import *

MARCA = {"nombre": "GASOLINERAS", "color": "#C4372C", "claro": "#FFE14D", "oscuro": "#3A0F12", "acento": "#FFD95A"}
G = Guion("gasolineras", MARCA)
DOS, SOL, RUTA, MESA = "f_dos", "traffic_sunset", "truck_highway_bridge", "calculator_papers"


def P(de, pasos, items, clips=None, **k):
    # la calle de las dos gasolineras solo en uno de cada dos planos: el resto, trafico
    if clips == [DOS]:
        P.n += 1
        if P.n > 5 and P.n % 2:
            clips = [("aerial_roundabout", "trucks_highway_aerial", "aerial_highway", "traffic_sunset")[(P.n // 2) % 4]]
            k["luz"] = 0.62
        elif "luz" not in k:
            k["luz"] = 0.72
    G.plano(de, pasos, items, clips=clips, **k)


P.n = 0
